"连续普攻第 3 击命中后，可在收招时冲刺追步；紫金阶可改接技能。": "세 번째 일반 공격이 적중한 뒤 대시 캔슬로 후딜을 끊고 추격 걸음으로 이어집니다. 자금 등급은 기술로 연결할 수 있습니다.",
"蓄力斩命中后，下一次格挡交锋会减少击退；紫金阶技能也可承接。": "차지 공격이 적중한 뒤 다음 방어 교환에서 밀려나는 거리가 줄어듭니다. 자금 등급은 효과를 기술로 이어갈 수 있습니다.",
"精准招架后，限时重击会向前踏进，抓住反击时机。": "저스트 가드 뒤에 제때 시작한 강공격이 앞으로 나아가며 반격합니다.",
"破防后立刻重置冲刺冷却，下一次冲刺可更快追击；紫金阶也可选重击踏进。": "가드를 깨면 대시 쿨타임이 초기화되고 다음 추격 대시가 강화됩니다. 자금 등급은 대신 강공격으로 파고들 수 있습니다.",
"腾空攻击命中后可续一次空中冲刺；紫金阶可接空中技能。": "공중 적중 시 소모한 공중 대시를 1회 회복합니다. 자금 등급은 공중 후딜을 기술로 캔슬할 수 있습니다.",
"闪避后命中，可在收招时冲刺退步；紫金阶退步带短暂无敌。": "회피 반격 뒤 대시 캔슬로 후딜을 끊고 물러납니다. 자금 등급은 이동하는 동안 잠깐 회피 효과를 얻습니다.",
"0.65 秒内可用冲刺取消收招。": "0.65초 이내에 대시 캔슬로 후딜을 끊습니다.",
"窗口延长 15%。": "유효 시간이 15% 늘어납니다.",
"窗口延长 30%，并可用一次技能取消收招。": "유효 시간이 30% 늘어나고 기술 캔슬을 1회 허용합니다.",
"0.8 秒内下一次格挡击退降低 28%。": "0.8초 이내의 다음 방어에서 밀려나는 거리가 28% 줄어듭니다.",
"窗口延长 30%，且技能命中也可消耗压迫效果。": "유효 시간이 30% 늘어나며, 기술이 적중해도 압박 효과를 소모할 수 있습니다.",
"0.65 秒内重击向前踏进。": "0.65초 이내에 시작한 강공격이 앞으로 나아갑니다.",
"踏进距离略增。": "파고드는 거리가 조금 늘어납니다.",
"破防后重置冲刺冷却，下一次冲刺距离略增。": "가드를 깨면 대시 쿨타임이 초기화되고, 다음 대시가 조금 더 멀리 나아갑니다.",
"追击窗口延长 15%。": "추격 유효 시간이 15% 늘어납니다.",
"窗口延长 30%，并可选择重击踏进追击。": "유효 시간이 30% 늘어나고 강공격 파고들기 추격을 선택할 수 있습니다.",
"空中冲刺用尽后，命中可恢复一次并在收招时续闪。": "공중 대시를 소모한 뒤 공중 적중 시 1회 회복하고 대시 캔슬로 후딜을 끊을 수 있습니다.",
