"自动保存最近 10 场可回放战斗（本地对战、模式变式与联机），保存在这台设备的浏览器里。回放可暂停、慢放、快进，也能导出导入，与人对传。": "로컬, 변형, 온라인 모드를 통틀어 최근 리플레이 가능한 대전 10개가 이 브라우저에 저장됩니다. 리플레이는 일시정지, 느리게, 빠르게 재생할 수 있고, 내보내기와 가져오기로 공유할 수 있습니다.",
"「训AI」导出的是这一局真实采集的逐帧数据：s 是 19 维状态（双方血量、护甲、内力、奥义槽、站位、朝向、滞空、硬直、是否正对），a 是这一帧按住的键（位掩码），r 由本帧双方回血/掉血和终局胜负算出。.jsonl 训练集可以导入合并、再整包导出。": "\"학습\"은 해당 대전에서 실제로 기록된 프레임을 내보냅니다. s는 19개 값으로 된 상태(양측의 체력, 방어, 내공, 필살기 게이지, 위치, 방향, 공중 여부, 경직, 서로 마주 봄), a는 그 프레임에서 누른 키(비트마스크), r은 그 프레임의 체력/방어 변화와 최종 결과에서 나옵니다. .jsonl 학습 세트는 가져오고, 병합하고, 하나의 파일로 내보낼 수 있습니다.",
