"云端已连接，但当前为本机账号。点击【一键升级为云端账号】即可将进度上传到云端！": "클라우드에는 연결되어 있지만 로컬 계정입니다. 클라우드 계정으로 업그레이드를 눌러 진행 상황을 업로드하세요!",
