"支持上传你导出的存档文件 (.json) 恢复英雄、皮肤、墨锭与战绩：": "내보낸 저장 파일(.json)을 업로드해 협객, 스킨, 먹, 기록을 복원하세요:",
"支持任一 renying-account 备份文件": "renying-account 백업 파일이면 모두 사용할 수 있습니다",
