"分析结合双方侠客、技能、站位与输入，给出可复核的战术选择建议。": "분석은 양쪽 협객, 기술, 간격, 입력을 종합해 리플레이에서 직접 확인할 수 있는 전술 선택지를 제시합니다.",
"做得好": "잘한 점",
"可改进": "개선할 점",
"下一步": "다음 단계",
"对局统计已保存，可在回放中复核攻防交换。": "대전 통계가 저장되었으니 리플레이에서 교환 장면을 복기할 수 있습니다.",
"承受伤害明显高于输出，交换中还可以减少硬吃招式。": "가한 피해보다 받은 피해가 훨씬 많았습니다. 공격을 무릅쓰고 맞교환하는 것은 피하세요.",
"把回放频率调到 1 Hz 并打开判定框，确认攻击范围覆盖对手后再出手。": "리플레이를 1Hz로 설정하고 판정 상자를 표시해 공격하기 전에 사거리를 확인하세요.",
"起手前确认朝向，必要时先用方向键调整再攻击。": "공격을 시작하기 전에 방향을 확인하고, 필요하면 방향키로 조정하세요.",
"现有数据未发现明显的远距离出手或失衡交换。": "확보된 데이터에는 원거리 공격이나 불리한 맞교환의 뚜렷한 패턴이 없습니다.",
"先练习格挡与腾空闪，等对手招式结束后再反击。": "막기와 탈출 섬광을 연습한 뒤 상대의 기술이 끝난 다음 반격하세요.",
"把对手引向场地内侧，自己靠近边缘时优先撤回安全位置。": "상대를 중앙으로 끌어들이고, 가장자리 근처에서는 안전한 곳으로 물러나세요.",
"用慢放和判定框复核命中后的硬直窗口，再练习一套稳定的追击。": "슬로모션과 판정 상자로 경직을 복기한 뒤 확실한 후속타를 연습하세요.",
"关键时刻来自录像中的抽样状态与输入，点击可跳到对应回放帧。": "핵심 장면은 표본 추출한 리플레이 상태와 입력을 사용합니다. 하나를 선택하면 해당 리플레이 프레임으로 이동합니다.",
