"断崖台": "절벽",
"两侧没有墙。被击飞出崖边会坠崖，扣一点气血后弹回台上。": "양쪽에 벽이 없습니다. 가장자리 너머로 날아가면 추락해 체력을 조금 잃고 다시 튀어 오릅니다.",
"寒潭冰面": "얼어붙은 연못",
"中间是一片冰面：起步和停下都会打滑，越重滑得越远。": "가운데가 얼음입니다. 출발하고 멈출 때 미끄러지며 무거운 협객일수록 더 멀리 미끄러집니다.",
"冰上如履平地：抓地力至少是平地的八成。": "얼음 위에서도 안정: 접지력이 평지의 80% 아래로 떨어지지 않습니다.",
"千斤坠地：冰上抓地力至少是平地的九成。": "뿌리내린 자세: 얼음 위 접지력이 평지의 90% 아래로 떨어지지 않습니다.",
"竹海悬岩": "대나무 언덕",
"两侧竹台高悬，跳得上去，按住 ↓ 再跳落下。每 18 秒刮 6 秒强风，顺风走得快、飞行道具飞得快。": "양쪽에 대나무 발판이 걸려 있습니다. 점프한 뒤 ↓를 누른 채 점프하면 내려옵니다. 18초마다 6초간 질풍이 불어 바람을 탄 이동과 투사체가 빨라집니다.",
"剑气借风：顺风的飞行道具多飞一倍。": "바람 탄 칼날: 바람을 탄 투사체가 두 배로 가속됩니다.",
"乘风而行：顺风时风推得快一倍，逆风不受阻。": "바람 타기: 순풍이 두 배로 밀어 주고 맞바람은 속도를 늦추지 않습니다.",
"雷泽石坛": "뇌단",
"中央一座石坛。每 24 秒天雷落在石坛上空（提前 1.3 秒预警），站在坛上或在它上空的人被劈飞。": "중앙에 돌 제단이 있습니다. 24초마다 제단 위로 번개가 내리치며(1.3초 전 경고), 제단 위나 그 위 공중에 있는 사람을 띄웁니다.",
"引雷淬体：不怕天雷，被劈中反而回 35 点气，并得到 3 秒雷护。": "번개로 단련됨: 낙뢰에 면역이고, 피격 시 게이지 35와 3초간 뇌 방어를 얻습니다.",
"巨力镇坛：不怕天雷，劈中不伤也不浮空。": "흔들리지 않음: 낙뢰에 면역이며 피해를 받지 않고 땅에 머뭅니다.",
"皇城飞檐": "궁궐 처마",
"三重飞檐错落，跳得上去，按住 ↓ 再跳落下。两侧没有红柱，被击飞撞到边上不会弹墙。": "처마 세 층이 있습니다. 점프한 뒤 ↓를 누른 채 점프하면 내려옵니다. 양옆에 붉은 기둥이 없어 가장자리로 날아간 협객이 벽에 튕기지 않습니다.",
"飞檐走壁：站在飞檐上走得快 15%。": "지붕 달리기: 처마 위에 서 있는 동안 이동 속도 15% 증가.",
"檐上穿梭：站在飞檐上时，移形换影的冷却快 30%。": "처마 질주자: 처마 위에 서 있는 동안 그림자 교체 회복이 30% 빨라집니다.",
"醉翁墨阁": "취묵정",
"水榭两侧有亭台，中间一半飘着酒雾：站在雾里的地上，每秒回 2.5 点定力。": "양쪽에 정자가 있고 중앙 절반에는 술안개가 깔려 있습니다. 안개 속 땅에 서 있으면 초당 가드 2.5를 회복합니다.",
"酒香浸染：在酒雾里醉意每秒涨 12。": "술에 젖음: 안개 속에서 취기가 초당 12씩 오릅니다.",
"水榭湿润：在酒雾里定力回得快一倍。": "눅눅한 정자: 안개 속에서 가드가 두 배 빨리 돌아옵니다.",
