"竹林里妖气初起，第一批侠客拔剑入林。": "대숲에서 마기가 꿈틀거리고, 첫 협객들이 검을 뽑습니다.",
"夜枭鸣山": "산에서 우는 부엉이",
"夜枭整夜啼叫，山里的路越来越难走。": "부엉이가 밤새 울고 산길은 위험해집니다.",
"刀鬼出鞘": "칼 귀신이 칼을 뽑다",
"刀鬼成群下山，见人就砍。": "칼 귀신이 무리 지어 산을 내려와 마주치는 이를 베어 넘깁니다.",
"弓妖伏道": "매복한 궁수 마물",
"弓妖埋伏在道旁，过路的商队不敢出门。": "궁수 마물이 길가에 매복해 있어 대상이 더는 다니지 못합니다.",
"古道迷踪": "옛길에서 길을 잃다",
"古道上起了雾，走进去的人没有回来。": "옛길에 안개가 내려앉아 들어간 이들이 돌아오지 못했습니다.",
"缚灵夜行": "속박자가 밤에 걷는다",
"缚灵趁夜出没，把人困在原地。": "속박자가 밤에 나타나 사람들을 제자리에 붙잡아 둡니다.",
"断桥残雪": "끊어진 다리의 눈",
"桥断了，雪地上全是妖物的脚印。": "다리가 끊어졌고 눈밭에는 마물의 발자국이 가득합니다.",
"荒驿孤灯": "빈 객잔의 등불",
"荒废的驿站里还亮着一盏灯。": "버려진 객잔에 등불 하나가 아직 타고 있습니다.",
"山寨狼烟": "요새 위의 연기",
"山寨升起狼烟，妖物占了寨子。": "요새 위로 연기가 솟습니다. 마물이 차지했습니다.",
"咒师聚众": "주술사들이 모이다",
"咒师聚在寨里，日夜念咒。": "주술사들이 요새에 모여 밤낮으로 주문을 읊습니다.",
"火柱连天": "불기둥",
"咒火一根接一根冲上天。": "저주받은 불기둥이 하나씩 하늘로 솟구칩니다.",
"寨门血誓": "요새 문 앞의 맹세",
"侠客们在寨门前立誓，不破此寨不回头。": "협객들이 요새가 무너질 때까지 물러나지 않겠다고 문 앞에서 맹세합니다.",
"魔窟初探": "마동 속으로",
"第一批侠客摸进了魔窟。": "첫 협객들이 마동으로 숨어듭니다.",
"妖王低语": "마왕의 속삭임",
"魔窟深处传来妖王的低语。": "마왕의 속삭임이 동굴 깊은 곳에서 들려옵니다.",
"血月当空": "떠오르는 혈월",
