"雾锁长亭": "장정의 안개",
"长亭被浓雾锁住，送别的人出不来。": "짙은 안개가 모두를 장정에 가두었습니다.",
"古刹钟鸣": "옛 절의 종",
"山中古刹的钟无人自鸣。": "옛 산사의 종이 저절로 울립니다.",
"鬼市开张": "귀시장이 열리다",
"半夜的鬼市开张了，卖的都是妖物的东西。": "한밤의 귀시장이 열렸고, 파는 물건은 모두 마물에게서 나온 것입니다.",
"风雪归人": "눈길 속 귀향",
"风雪里有人赶路回乡，侠客一路护送。": "나그네들이 눈길을 헤치고 고향으로 향하고 협객들이 호위합니다.",
"铁索横江": "강을 가로지른 쇠사슬",
"妖物用铁索拦住了江面。": "마물이 강을 쇠사슬로 막았습니다.",
"烽火连营": "봉화",
"一座座营寨点起烽火，江湖都动了起来。": "온 땅이 일어나며 진영마다 봉화가 밝혀집니다.",
"天道初现": "천도의 출현",
"天上裂开一道口子，天道第一次露了面。": "하늘이 갈라지며 천도가 처음으로 모습을 드러냅니다.",
"星落平野": "평원에 떨어진 별",
"星星落在平野上，砸出一个个妖穴。": "평원에 별이 떨어지고 내려앉은 자리마다 마물의 둥지가 생깁니다.",
"寒潭映月": "차가운 못 속의 달",
"寒潭底下有东西在动。": "차가운 못 바닥에서 무언가가 움직입니다.",
"百鬼夜行": "백귀야행",
"一百只妖物排成一列，在夜里穿过村庄。": "백 마리의 마물이 밤에 마을을 행진합니다.",
"孤城落日": "외로운 성의 석양",
"孤城被围，城头只剩几位侠客。": "외로운 성이 포위되어 성벽 위에는 협객 몇 명만 남았습니다.",
"剑冢问心": "검총의 물음",
"剑冢里的旧剑在问来人为什么拔剑。": "검총의 옛 검들이 찾아온 이마다 왜 싸우느냐고 묻습니다.",
"金鼓雷鸣": "전쟁의 북소리",
"战鼓响起，全江湖一起出战。": "전쟁 북이 울리고 모든 협객이 출격합니다.",
"雁门秋声": "변방의 가을",
"雁群南飞，关外的妖物也跟着南下。": "기러기가 남쪽으로 날아가고 관문 너머의 마물이 뒤따릅니다.",
"墨雨江南": "남쪽의 먹비",
"江南下起墨一样的雨。": "먹물 같은 비가 남쪽에 내립니다.",
"玉门关外": "옥문관 너머",
"关外的风沙里藏着妖物的大营。": "마물의 본진이 관문 너머 모래폭풍 속에 숨어 있습니다.",
"大漠孤烟": "사막의 연기",
"大漠里只有一缕烟，那是妖物的信号。": "사막에 연기 한 줄기가 솟습니다. 마물이 보내는 신호입니다.",
"黄沙埋骨": "모래 속의 뼈",
"黄沙底下埋着上一代侠客的剑。": "지난 협객들의 검이 모래 아래 묻혀 있습니다.",
"天山雪莲": "천산설련",
"天山上的雪莲能解妖毒，妖物守着不让采。": "설련은 마물의 독을 치료하지만 마물이 단단히 지키고 있습니다.",
"昆仑云深": "곤륜의 구름",
"昆仑山云很深，妖王的影子在云里走。": "곤륜의 구름이 깊고 마왕의 그림자가 그 속을 걷습니다.",
"蜀道难行": "촉도난",
"蜀道上的妖物把栈道一段段拆了。": "마물이 산 위 잔도를 하나씩 허물고 있습니다.",
"巫峡猿啼": "협곡의 원숭이 울음",
"峡里的猿啼声变成了妖物的嘶吼。": "협곡의 원숭이 울음이 마물의 울부짖음으로 변했습니다.",
"洞庭秋水": "동정호의 가을",
"洞庭湖水变黑了。": "호수의 물이 검게 변했습니다.",
"岳阳论剑": "악양의 검담",
"各路侠客在楼上论剑，商量最后一战。": "각지의 협객이 누각에 모여 마지막 전투를 논의합니다.",
"姑苏夜泊": "고소의 밤 정박",
"夜里泊船的地方，妖物从水里爬上来。": "배가 밤에 정박하는 곳에서 마물이 물 밖으로 기어 나옵니다.",
"钱塘潮起": "전당강 밀물",
"大潮里卷着成群的妖物。": "거대한 밀물이 마물 떼를 함께 실어 옵니다.",
"东海蓬莱": "동해의 봉래",
"海上的仙山也被妖气染黑了。": "신선의 섬마저 마기로 검게 물들었습니다.",
"天涯海角": "땅끝",
"一路打到天涯海角，妖物已经无处可退。": "싸움이 땅끝에 이르러 마물은 더 도망칠 곳이 없습니다.",
"万妖归墟": "모든 마물이 심연으로 달아나다",
"所有的妖物都往归墟退去。": "모든 마물이 심연을 향해 후퇴합니다.",
"魔首将醒": "마왕이 꿈틀거리다",
"归墟深处，融魂魔首快要醒了。": "심연 깊은 곳에서 융합 마왕이 깨어나려 합니다.",
"天道裁决": "천도의 심판",
"天道亲自出手，要看江湖配不配活下去。": "천도가 나서서 세상이 살아남을 자격이 있는지 심판합니다.",
"江湖同归": "모든 협객이 함께",
"全江湖的侠客站到了一起。": "천하의 모든 협객이 한자리에 섭니다.",
"长卷余韵": "대전투 이후",
"大战过后，江湖还要守下去。": "대전투는 끝났지만 땅은 여전히 지켜야 합니다.",
"妖物越聚越多，先把眼前的清干净。": "마물이 계속 모여들고 있습니다. 먼저 눈앞의 마물부터 처치하세요.",
"有村子求救，侠客们连夜赶去。": "한 마을이 도움을 청하고 있어 협객들이 밤새 달려갑니다.",
"妖气散了一些，还不够。": "마기가 조금 옅어졌지만 아직 충분하지 않습니다.",
"一路斩过去，给后来的人开出一条路。": "뒤따르는 이들이 지나갈 수 있도록 길을 뚫으세요.",
"这一段的妖物最凶，全服的侠客往这里聚。": "이곳의 마물이 가장 사납고, 모든 채널의 협객이 이쪽으로 향하고 있습니다.",
"有人在这一段失踪了，去把他找回来。": "이곳에서 누군가 실종되었습니다. 찾아서 데려오세요.",
"守住这一段，别让妖物往外走。": "이 지역을 지켜 마물이 빠져나가지 못하게 하세요.",
"这一段的土地庙快守不住了。": "이 지역의 사당이 곧 무너집니다.",
"妖王又出来了，这次要把它打回去。": "마왕이 다시 나타났습니다. 이번에는 물리치세요.",
"妖王身上带着线索，得打倒它才拿得到。": "마왕이 단서를 지니고 있습니다. 쓰러뜨려야 얻을 수 있습니다.",
"妖王在魔窟里召集手下。": "마왕이 동굴에서 추종자들을 모으고 있습니다.",
"打倒妖王，魔窟会安静一阵子。": "마왕을 쓰러뜨리면 동굴이 한동안 잠잠해집니다.",
"一劫一劫地斩过去，天道在看着。": "시련을 하나씩 돌파하세요. 천도가 지켜보고 있습니다.",
"每斩完一劫，江湖就稳一分。": "시련을 하나 돌파할 때마다 땅이 조금 더 안전해집니다.",
"劫数未尽，不能停手。": "시련은 끝나지 않았으니 지금 멈추지 마세요.",
"斩完这几劫，下一段路才会打开。": "이 시련을 돌파하면 앞길이 열립니다.",
"这一章到了最后，天道派来了守关的人。": "이 장이 끝나가며 천도가 수호자를 보냈습니다.",
"关键战打赢了，这一章才算写完。": "중요 대결에서 승리해 이 장을 끝내세요.",
"全线一起出手，赢下这一战。": "모든 채널이 함께 쳐서 이 싸움에서 승리하세요.",
