"前往对战电脑": "AI 대전으로 이동",
"墨球蹴鞠": "먹 공",
"不比气血，比谁先进三球": "체력 바 없음, 3골 선취",
"墨球蹴鞠 · 先进三球": "먹 공 · 3골 선취",
"不比气血 · 不计排位": "체력 없음 · 비랭크",
"场地两边各有一个球门，中间一颗墨球。普攻和技能打中墨球就能把它打飞，先把墨球打进对方球门三次的一方获胜；时间到比分领先的赢，平分进金球决胜。挨打照样会被打飞，但气血不会掉。": "양 끝에 골대가 있고 가운데에 먹 공이 있습니다. 공격과 기술로 공을 쳐서 날려 보내세요. 상대 골대에 먼저 세 번 넣는 쪽이 이깁니다. 시간이 끝나면 앞선 쪽이 이기고, 동점이면 골든 골로 가립니다. 타격은 협객을 밀어내지만 아무도 체력을 잃지 않습니다.",
"踢法": "킥",
"每位侠客都有自己的踢法": "협객마다 자기만의 방식으로 공을 찹니다",
"重击、↑ 挑射、↓ 贴地抽射、空中头槌砸球，移动带球过人，格挡扑救（精准格挡可触发神扑）。勾陈飞锤勾球、磁仙正负磁极吸弹、千机傀儡与离影分身皆可截球或协同踢法。": "강타, ↑ 로브, ↓ 낮은 슛, 공중 헤딩. 이동 중 드리블, 막기로 선방(저스트 가드는 슈퍼 세이브). 구진은 공을 갈고리로 당기고, 자선은 장대로 끌어당기거나 밀어내며, 천기의 꼭두각시와 이영의 분신은 공을 걷어내거나 슛할 수 있습니다.",
"先3球": "3골 선취",
