"本地双人对踢": "로컬 2인",
"本地双人：1P 用 WASD + X 或鼠标，2P 用方向键 + K 攻击、U 和 O 放技能、I 放大招。": "로컬 2인: 1P는 WASD + X 또는 마우스, 2P는 방향키, K로 공격, U와 O로 기술, I로 필살기를 사용합니다.",
"不比气血比进球：用普攻和技能把墨球打进对方球门，先进三球获胜": "체력이 아닌 골: 공격과 기술로 먹 공을 상대 골대에 넣으세요. 3골을 먼저 넣으면 승리합니다",
