"三层断崖高台上轮流浮现灵坛。站入无人争抢的灵坛即可累积占领进度，先达 100% 一方获胜！阵亡或落崖后 2.5 秒重返战场。": "제단이 세 개의 절벽 발판 위를 돌며 옮겨 갑니다. 방해받지 않고 안에 서 있으면 점령도가 100%까지 오릅니다. 장외 추락과 KO는 2.5초 뒤에 부활합니다.",
