"江湖百戏 · 五局三胜": "엉뚱한 시련 · 5판 3선승",
"趣味轮换 · 不计排位": "순환 미니게임 · 비랭크",
"每回合轮换不同规则：传火折（击中对手把定时火折传出去）、断崖推手（无伤 2.6 倍击退把人推下悬崖）、飞球乱舞（格挡弹开飞球，砸中即出局）。": "라운드마다 규칙이 바뀝니다. 폭탄 돌리기(때려서 째깍거리는 폭탄 넘기기), 절벽 스모(피해 0, 넉백 2.6배), 먹 피구(막으면 튕겨내고, 맞으면 KO).",
"对战电脑 · 百戏": "AI 대전 · 시련",
"本地双人百戏": "로컬 2인 시련",
"五局三胜趣味百戏：传火折、断崖推手、飞球乱舞轮换上阵": "5판 3선승 순환 파티 미니게임: 폭탄 돌리기, 절벽 스모, 피구",
"传火折": "폭탄 돌리기",
"挨打接火折，倒计时归零即炸！": "터지기 전에 때려서 째깍거리는 폭탄을 넘기세요!",
"断崖推手": "절벽 스모",
"无伤 2.6 倍击退，把对手推下悬崖！": "피해 0, 넉백 2.6배 — 상대를 장외로 밀어내세요!",
"飞球乱舞": "먹 피구",
"格挡弹飞墨球，被砸中直接出局！": "공을 막아 튕겨내지 않으면 KO됩니다!",
"传火!": "넘겼다!",
"火折爆裂!": "쾅!",
"救起同袍": "아군 부활",
"靠近救起": "서서 부활시키기",
"破防虚弱!": "휘청!",
"坠崖出局": "장외 추락!",
"玩法说明": "모드 안내",
"关闭说明": "안내 닫기",
"对战电脑 · 玩法说明": "AI 대전 · 모드 안내",
"3v3 车轮战 · 玩法说明": "3대3 릴레이 · 모드 안내",
"双方各选三名侠客并排定先锋、中坚、大将顺序。每局胜者保留残血小幅调息迎战下一位对手，先把对方三将全数击破的一方获胜。": "양측이 선봉/대장 순서로 협객 3명씩 선발합니다. 라운드 승자는 남은 체력을 안고 다음 상대와 싸우며, 한 쪽 부대가 쓰러질 때까지 이어집니다.",
"2v2 组队 · 玩法说明": "2대2 팀 · 모드 안내",
"四人同屏大场地混战（2600px 宽）。支持「你 + 电脑队友」、本地双人打两电脑、本地四人互打，以及全 AI 天道演武观战。": "너비 2600px의 넓은 무대에서 벌이는 4인 난투. 나 + AI, 로컬 2P 대 AI 2명, 로컬 4인, 전체 AI 관전을 지원합니다.",
"墨球蹴鞠 · 玩法说明": "먹 공 · 모드 안내",
"双方不扣气血，比谁先把墨球打进对方球门（默认先 3 球，可选 5/7 球）。普攻与技能可抽射/挑射墨球，格挡可扑救，精准格挡触发神扑！": "체력 손실 없음. 먹 공을 쳐서 상대 골대에 넣어 득점하세요(3/5/7골 선취). 막으면 선방, 저스트 가드는 슈퍼 세이브입니다!",
"灵坛争锋 · 玩法说明": "제단 점령 · 모드 안내",
"三层断崖高台上每 18 秒轮流激活灵坛。站入无人争抢的灵坛即可累积占领进度，先达 100% 获胜；阵亡或被打落悬崖后 2.5 秒重返战场。": "18초마다 세 절벽 발판 중 한 곳에서 제단이 활성화됩니다. 방해받지 않고 안에 서 있으면 100%에 도달합니다. KO와 절벽 장외 추락은 2.5초 뒤에 부활합니다.",
"江湖百戏 · 玩法说明": "엉뚱한 시련 · 모드 안내",
"五局三胜趣味小游戏轮换：第一局「传火折」（击中对手把 9 秒火折传出去，归零即炸）、第二局「断崖推手」（0 伤害但 2.6 倍击退，推落悬崖即胜）、第三局「飞球乱舞」（格挡弹反飞球，砸中即出局）。": "5판 3선승 순환 미니게임: 폭탄 돌리기(때려서 9초 폭탄 넘기기), 절벽 스모(피해 0, 넉백 2.6배 장외전), 먹 피구(막으면 튕겨내고 못 막고 맞으면 KO).",
"训练场 · 玩法说明": "훈련 · 모드 안내",
"包含招式教学、木人桩自由练习（可看判定框、帧数差与回放）、以及防反/连段等专项情景训练。": "안내식 기술 튜토리얼, 판정 상자와 프레임 이득을 볼 수 있는 자유 연습, 집중 상황 훈련이 포함됩니다.",
"守关挑战 · 玩法说明": "캠페인 · 모드 안내",
"十三侠客专属六章三十关斩妖除魔路线。每关击败首领积累星级与墨锭，最终章迎战六技融魂魔首。": "모든 협객을 위한 6개 장, 30개 스테이지의 마물 토벌 캠페인으로, 특수기 6개를 지닌 보스와의 협동 결전으로 끝납니다.",
"侠客列传 · 玩法说明": "협객 대서사 · 모드 안내",
"每位侠客独立的五节剧情篇章，在关键节点做出抉择可解锁不同结局与专属秘闻。": "협객마다 5막으로 구성되며 갈림길 선택과 두 가지 엔딩이 있는 이야기입니다.",
"问剑密卷 · 玩法说明": "끝없는 탑 · 모드 안내",
"无尽爬塔肉鸽试炼：每层获胜后三选一武林秘卷叠加词条，守关 AI 境界随层数递进。": "끝없는 로그라이크 등반: 층이 끝날 때마다 비급 3장 중 1장을 고르며 AI 도전자는 점점 영리해집니다.",
"天枢守境": "천추 요새",
