"时辰已到": "시간 종료",
"再战一次": "다시 싸우기",
"返回列传": "대서사로 돌아가기",
"最近走完的：": "최근 완료:",
"所有在线玩家都能看到，点名字可以加好友": "온라인의 모든 사람이 볼 수 있습니다. 이름을 누르면 친구로 추가합니다",
"正在连接大厅…": "대기실에 연결하는 중…",
