"个星座武器箱": "황도 상자",
"个天工传世匣": "가보 유물함",
"普通和神兵武器箱每天零点刷新，星座与天工传世匣每周一刷新；武器箱在商店按固定价格买，不限量": "일반과 신병 상자 한도는 자정에, 황도와 가보 유물함은 월요일에 초기화됩니다. 상자는 상점에서 고정 가격으로 제한 없이 판매합니다",
"拥有": "보유",
"十二星座，每位侠客都有星辉、星焰、星冕三款。每个号都送了 1 个星座武器箱，可以先免费开一次。": "열두 별자리마다 모든 협객에게 별빛, 별불꽃, 별의 관 버전이 있습니다. 모든 계정에 체험용 황도 상자 1개가 무료로 지급됩니다.",
"未集齐": "미완성",
"看看穿上的样子": "미리보기:",
"逐台开封": "하나 열기",
"买一台": "하나 구매",
"货郎报价的概率": "행상 제안 확률",
"每件都从全部武器箱饰品里抽取（含神兵与星座武器箱），支持逐台挑货或一键批量开启": "모든 제안은 상자 장식품 전체(신병과 황도 포함)에서 뽑히며, 하나씩 확인하거나 한꺼번에 열 수 있습니다",
"一键开启全部会一次性打开所有可用货郎并直接将奖励收入库存；逐台开封时 5 件都不要或 3 天内不处理会作废。": "모두 열기는 가능한 모든 행상을 한꺼번에 열고 보상을 모두 보관함에 바로 추가합니다. 하나씩 열 때 제안 5개를 모두 건너뛰거나 3일간 방치하면 만료됩니다.",
"可逐台开封挑选报价，或直接一键开启全部货郎，一次性领取所有奖励。": "하나씩 열어 제안을 확인하거나, 가능한 모든 행상을 한꺼번에 열어 보상을 모두 받으세요.",
"在卖的饰品": "판매 중",
"我的挂单": "내 판매 목록",
"成交记录": "판매 기록",
"玩家市场只卖饰品：每一件都是别的玩家挂的，标价全由卖家自己定，系统不定价、也不收购；成交扣 15% 手续费。武器箱和货郎在商店按固定价格买。": "플레이어 장터에서는 장식품만 판매합니다. 모든 물건은 다른 플레이어가 정한 가격으로 등록되며, 게임이 가격을 정하거나 물건을 사들이지 않고, 판매마다 수수료 15%가 붙습니다. 상자와 행상은 상점에서 고정 가격으로 판매합니다.",
"玩家市场要登录云端账号、连上服务器才能用：本机存档只能开箱、熔铸，不能和别的玩家买卖。": "플레이어 장터는 클라우드 계정과 서버 연결이 필요합니다. 로컬 저장으로는 상자를 열고 재련할 수 있지만 다른 플레이어와 거래할 수 없습니다.",
"只看有人在卖的": "판매 중인 물건만",
"没人在卖": "판매 중인 물건 없음",
