"点一下放进合同": "눌러서 계약에 추가",
"库存里没有这一档的饰品。": "이 등급의 장식품이 없습니다.",
"星章": "별",
"每周一换四个任务，完成拿星章，星章换武器箱、货郎、改名标签和饰品。": "매주 월요일에 새 임무 4개가 열립니다. 완료하면 별을 얻고, 별로 상자, 행상, 이름표, 장식품을 교환할 수 있습니다.",
"本周任务": "이번 주 임무",
"每周补给": "주간 보급",
"已解锁：四样里挑两样": "해금됨: 4개 중 2개 선택",
"星章兑换": "별 교환소",
"饰品都从普通武器箱里出，神兵、星座武器箱的换不到": "장식품은 일반 상자에서 나오며, 신병과 황도 아이템은 교환할 수 없습니다",
"随机武器箱": "무작위 상자",
"随机碧玉饰品": "무작위 비취 장식품",
"随机灵犀饰品": "무작위 정령 장식품",
"自选赤霄饰品": "원하는 진홍 장식품",
"（武库获取或破关解锁）": "(무기고 또는 스테이지 클리어로)",
"个 · 商店价": "· 상점 가격",
"攻击硬直更长，伤害略低，攻击距离缩短。": "경직 시간이 길어지고 피해가 조금 줄어들며 사거리가 짧아집니다.",
"轻击判定更窄更远，蓄力斩后摇增加。": "약공격 판정이 좁아지고 더 멀리 닿으며, 차지 베기는 회복이 느려집니다.",
"打开连段追步窗口；紫金阶可改接技能。": "추격 걸음 구간이 열립니다. 자금 등급에서는 대신 기술로 캔슬할 수 있습니다.",
"下一次格挡交锋减少击退；紫金阶技能也可承接。": "다음 방어 교환에서 밀려나는 거리가 줄어듭니다. 자금 등급에서는 기술도 이 효과를 쓸 수 있습니다.",
"重击获得短促踏进，抓住招架后的反击时机。": "강공격이 짧게 파고들어 패링 뒤의 반격 구간을 잡습니다.",
"立刻重置冲刺冷却；紫金阶可选重击踏进追击。": "대시 쿨타임이 즉시 초기화됩니다. 자금 등급에서는 강공격으로 파고들어 추격할 수 있습니다.",
"腾空时最多续一次空中冲刺；紫金阶可接空中技能。": "공중에서 공중 대시를 최대 1회 회복합니다. 자금 등급에서는 공중 기술로 캔슬할 수 있습니다.",
"打开退步窗口；紫金阶退步带短暂无敌。": "후퇴 걸음 구간이 열립니다. 자금 등급에서는 걸음 중 잠깐 무적이 됩니다.",
"窗口延长 30%，踏进距离略增。": "유효 시간 30% 증가, 파고드는 거리 소폭 증가.",
"链锤强袭：近崖拽击力道强劲，坠崖判定门槛降低。": "연쇄 공격: 절벽 근처에서 끌어당기는 기술이 더 강하게 적중하고 상대를 더 쉽게 낭떠러지로 밀어냅니다.",
"极性推拒：两极磁场排斥增强，更易将敌弹落断崖。": "극성 반발: 더 강한 자기 밀침으로 적을 절벽 아래로 떨어뜨리기 쉬워집니다.",
"凌空渡虚：浮空滞空与三段跳，身处险境不易失足。": "하늘 걸음: 체공과 3단 점프로 떨어지기 어렵습니다.",
"羽行御风：空中滑翔平稳无阻，坠崖受到伤害减半。": "깃털 활공: 부드럽게 활공하며 절벽 추락 피해가 절반입니다.",
"寒枪扼险：长枪突刺压制崖口，近崖击退力度提升 20%。": "가장자리의 창: 창 찌르기가 절벽 가장자리를 제압하며 절벽 근처 넉백 +20%.",
"踏雪无痕：冰面疾行与闪步突进速度提升 15%。": "흔적 없는 걸음: 얼음 위에서 달리기와 대시가 15% 빨라집니다.",
"顺风滑斩：冰面冲刺轻击滑行追击，招式连贯流畅。": "미끄러지는 베기: 대시와 약공격이 얼음 위를 미끄러져 부드럽게 이어집니다.",
"冰魄机轮：玄铁傀丸在冰面上极低阻力滑行更快更远。": "얼음 톱니바퀴: 철 꼭두각시 구슬이 얼음 위에서 더 빠르고 멀리 미끄러집니다.",
"顺风旋岚：大招龙卷风与旋风掌顺风速度与范围增加。": "순풍의 질풍: 필살기 회오리와 선풍장이 순풍 방향으로 속도와 사거리가 늘어납니다.",
"顺风泼墨：顺风甩墨泼洒射程增加 30%。": "순풍의 먹: 먹 튀김이 순풍 방향으로 30% 더 멀리 날아갑니다.",
"雾迷竹影：竹台高低借势布局，雾身消散时回气加倍。": "안개 낀 대나무: 높은 대나무 발판을 쓸 수 있고, 안개 분신이 사라질 때 게이지를 두 배로 돌려줍니다.",
"雷鸣琴音：石坛回响，天雷降临时音律充能提速。": "천둥 가락: 돌 제단이 울려 퍼지고 번개가 내리는 동안 음표가 더 빨리 충전됩니다.",
"镜光引雷：明镜初现可折射天雷震荡，受到天雷伤害减半。": "거울 번개: 달거울이 번개를 튕겨 낼 수 있고, 번개가 주는 피해가 절반입니다.",
"雷磁共振：雷云笼罩期间，磁场吸引与斥力范围扩大 25%。": "천둥 공명: 먹구름이 무대를 덮고 있는 동안 자기 끌어당김과 밀침 범위 +25%.",
"高台清乐：立于檐角弹奏，音律波及范围增大 20%。": "높은 가락: 처마 위에서 연주하면 음표 사거리가 20% 늘어납니다.",
"居高布机：高檐投掷机关傀丸弹跳弧线更加开阔。": "고지대 장치: 처마에서 던진 꼭두각시 구슬이 더 넓은 호를 그리며 튕깁니다.",
"俯冲破风：飞檐起跳滞空时间更长，空中出招判定更广。": "급강하 바람: 처마에서의 점프가 더 오래 떠 있고 공중 공격이 더 넓은 범위를 덮습니다.",
"清露润镜：酒雾中脱战回复生命速度提升 50%。": "이슬 맺힌 거울: 술안개 속에서 비전투 중 회복이 50% 빠릅니다.",
"雾影重重：酒雾之中雾身更凝练，打碎雾身反震对手。": "겹겹의 안개: 술안개 속에서 안개 분신이 더 단단하고, 부수면 공격자가 충격을 받습니다.",
"机簧润滑：酒雾浸润傀丸，蓄力出击冷却恢复提速。": "기름 스민 샘: 술안개가 꼭두각시 구슬을 적셔 차지 공격 회복이 빨라집니다.",
