"解锁": "해금",
"上手打法": "플레이 팁",
"推荐连招": "기본 콤보",
"攻守均衡，借疾风斩穿身抢先手，再用弧月剑气远程压制。": "균형형 협객: 질풍참 관통으로 시작해 초승달 검기로 거리를 벌리세요.",
"J J J → Q 疾风斩 → 右键 弧月剑气": "J J J -> Q 질풍참 -> 우클릭 검기",
"高机动刺客，用烟幕隐身绕背偷袭，打完一套立刻拉扯。": "고기동 암살자: 그림자 걸음으로 뒤를 잡아 폭딜을 넣고 빠지세요.",
"Q 瞬影步 → J J J → 右键 飞镖": "Q 그림자 걸음 -> J J J -> 우클릭 쿠나이",
"重装霸体强压正面，靠蓄力重斩与山崩破防一锤定音。": "중무장 저거너트: 정면으로 압박하고 차지 공격과 눈사태로 가드를 부수세요.",
"Q 震地 → 重击(U) → 右键 铁壁冲": "Q 지진 -> 강공격(U) -> 우클릭 철 파성추",
"长枪控距，中远距离点刺拉扯，找准破绽穿云枪连刺破防。": "중장거리 창 견제형: 거리를 두고 찌르다가 구름 관통으로 빈틈을 응징하세요.",
"J J → Q 穿云枪 → 右键 回马枪": "J J -> Q 구름 관통 -> 우클릭 후방 찌르기",
"中距风系消耗，折扇旋风控场弹开近身敌，趁浮空接连段。": "바람 견제형: 회오리 부채로 돌진하는 적을 밀어내고 공중에서 띄우세요.",
"右键 飞扇 → Q 疾风破 → J J J": "우클릭 날아가는 부채 -> Q 바람 가르기 -> J J J",
"近身拳脚爆发与受击反震，被连招时用雷铠打断反打。": "근접 난투가: 뇌갑으로 적의 콤보를 끊고 반격으로 터뜨리세요.",
"J J J → Q 奔雷拳 → 右键 撼地": "J J J -> Q 번개 주먹 -> 우클릭 땅 내리치기",
"消耗墨水布阵控场，留符叠满后开大招墨龙镇压全场。": "먹 조종가: 견제하며 부적을 쌓은 뒤 먹 용을 무대 전체에 풀어 놓으세요.",
"右键 泼墨 → Q 画符 → E 墨龙出海": "우클릭 먹 튀김 -> Q 부적 -> E 먹 용",
"架招反打核心，看准对手出手瞬间开月镜，接莲华连斩。": "반격 전문가: 달거울로 날아오는 공격을 패링하고 깔끔하게 응징하세요.",
"Q 月镜架招 → J J J → 右键 月轮": "Q 달거울 -> J J J -> 우클릭 달 고리",
"空中滞空游走，用翎羽远程消耗，抓准时机高空俯冲突袭。": "공중 교전가: 위에서 깃털로 괴롭히다가 급강하해 파고드세요.",
"W 起跳 → 右键 翎羽 → Q 俯冲": "W 점프 -> 우클릭 깃털 -> Q 하늘 급강하",
"音波控场与弹反飞行道具，攒满音律后引爆大招破魂。": "음파 조종가: 메아리 벽으로 투사체를 반사하고 음표를 쌓아 마무리 폭딜을 넣으세요.",
"右键 音浪 → Q 回音壁 → J J": "우클릭 음파 -> Q 메아리 벽 -> J J",
"喝满醉意强化招式，贴身滚打与醉拳浮空打乱对手节奏。": "취권 난투가: 술을 마셔 기술을 강화하고 구르기 공격으로 적을 흩뜨리세요.",
"Q 饮酒 → 右键 醉仙望月 → J J J": "Q 술 마시기 -> 우클릭 취월 -> J J J",
"链锤中远距离拉拽强开，把逃跑或高台上的敌人扯到身前。": "사슬 도리깨 그래플러: 도망치거나 위층에 있는 적을 근접 거리로 끌어오세요.",
"右键 飞锤勾拉 → J J → Q 旋风锤": "우클릭 갈고리 당기기 -> J J -> Q 회오리",
"飞梭挂雀芒印记，叠层后瞬移换影切入引爆打爆发。": "표식 암살자: 방추로 바늘 자국을 남긴 뒤 그림자 교체로 터뜨리세요.",
"右键 飞梭 → Q 移形换影 → J J J": "우클릭 방추 -> Q 그림자 교체 -> J J J",
"留下雾身制造双重剑气，利用换位躲招并打出背刺连击。": "분신 책략가: 안개 분신을 심어 파동을 두 번 쏘고 위치를 바꿔 배후를 찌르세요.",
"Q 留影 → 右键 影波 → Q 换位 → J J": "Q 안개 분신 -> 우클릭 그림자 파동 -> Q 교체 -> J J",
