"【星枢牵引 · 刻线聚元】星规流火与重力力场持续削防攒气；奥义「星宿归元」循星轨六连斩后合拢三臂重击。": "[별 축 당기기 · 새겨진 선이 기를 모음] 계기 불꽃과 중력장이 계속 방어를 깎으며 게이지를 쌓습니다. 필살기 \"천체 정렬\"은 별의 길을 따라 여섯 번 베고 세 팔을 모두 닫아 강타합니다.",
