"普攻甩墨 · 蓄力远 45% · 墨韵护体(825血)": "콤보가 먹을 흩뿌림 · 차지 사거리 +45% · 먹 방벽 (체력 825)",
"3 秒未受伤每秒回 14 血(780血)": "3초간 맞지 않으면 초당 체력 14 회복 (체력 780)",
"空中按住跳跃飞 1.2 秒(750血)": "공중에서 점프를 누르고 있으면 1.2초간 비행 (체력 750)",
"普攻攒音律，清音随音律变强(775血)": "콤보가 음표를 쌓고 맑은 음색이 그에 따라 강해짐 (체력 775)",
"醉意增伤，半醉可闪避近身攻击(885血)": "취기가 피해를 높이고, 반쯤 취하면 근접 공격을 피함 (체력 885)",
"被锤中的人 1.2 秒内受伤 +25%(835血)": "망치에 맞은 대상은 1.2초간 받는 피해 +25% (체력 835)",
"子母梭挂雀芒，换影穿刺引爆重置(790血)": "쌍북이 표식을 남기고 그림자 관통이 터뜨려 초기화 (체력 790)",
"疾风斩直击穿身，立时重置剑气冷却": "질풍참이 직격하면 관통하며 검기가 즉시 초기화됨",
"1.5 秒内再按 Q 瞬回原位": "1.5초 안에 Q를 다시 누르면 원래 있던 곳으로 되돌아감",
"震地直击得手，回涌 30 架势并减铁壁冲冷却": "지진이 직격하면 가드 30 회복, 철벽 돌진 쿨타임 감소",
"回马枪命中，枪旋冷却减半": "뒤 찌르기가 적중하면 창 회오리 쿨타임이 절반으로 줄어듦",
"风刃两道 · 开扇撒爆米花": "바람 칼날 둘 · 부채를 펼치면 팝콘이 흩어짐",
"雷闪冲拳命中，立时重置金刚雷铠冷却": "번개 주먹이 적중하면 금강 갑옷 쿨타임이 즉시 초기화됨",
"再按 Q 引爆墨阵": "Q를 다시 눌러 먹 함정을 터뜨림",
"格反成功，月轮冷却清零": "패링에 성공하면 달 수레 쿨타임이 사라짐",
"空中俯冲命中，可再冲一次": "공중 급강하가 적중하면 한 번 더 급강할 수 있음",
"回音壁能把暗器弹回去": "메아리 방벽이 투사체를 되받아침",
"酒过半壶可闪避近战，并可掷坛与民同乐回春": "호리병 절반을 넘으면 근접을 피하고, 병을 던져 함께 마시며 회복할 수 있음",
"飞锤拽到身前，接旋锤": "날아가는 망치로 끌어당긴 뒤 회오리로 이어가세요",
"雀芒印记配合换影穿刺，瞬发引爆清空冷却": "참새 낙인에 그림자 관통이 닿으면 즉시 터뜨리고 쿨타임이 초기화됨",
